class CartNotifier extends ChangeNotifier {
  bool _isLoading = false;
  bool _isSubmitting = false;
  Cart? cart;

  String? get currency => restaurant?.currency;

  String? get localizedCurrency => getLocalizedCurrency(currency);

  int get itemsCount => cart?.items.length ?? 0;

  bool get isLoading => _isLoading;

  set isLoading(bool loading) {
    _isLoading = loading;
    notifyListeners();
  }

  bool get isSubmitting => _isSubmitting;

  set isSubmitting(bool submitting) {
    _isSubmitting = submitting;
    notifyListeners();
  }

  Restaurant? restaurant;

  Future<void> initialize() async {
    _isLoading = true;
    notifyListeners();
    await cartRepo.clearAllItemsInCart();
    await fetchCart();
    _isLoading = false;
    notifyListeners();
  }

  Future<void> incrementItem(CartItem cartItem) async {
    final item = cart!.items.firstWhere((i) => i.id == cartItem.id);
    item.quantity += 1;
    notifyListeners();
    try {
      await cartRepo.incrementOrDecrementItem(cartItem, true);
      _updateTotal();
    } catch (e) {
      refresh();
    }
  }

  Future<void> decrementItem(CartItem cartItem) async {
    final item = cart!.items.firstWhere((i) => i.id == cartItem.id);
    item.quantity -= 1;
    if (item.quantity == 0) {
      cart!.items.remove(item);
    }
    notifyListeners();
    try {
      await cartRepo.incrementOrDecrementItem(cartItem, false);
      _updateTotal();
    } catch (e) {
      refresh();
    }
  }

